package com.trombokendu.chronos.selftest;import com.trombokendu.chronos.analytics.*;import com.trombokendu.chronos.domain.*;import com.trombokendu.chronos.ledger.*;import com.trombokendu.chronos.concurrency.*;import java.util.*;import java.time.*;import java.math.*;public final class SelfTests{private SelfTests(){}public static void main(String[]a)throws Exception{stats();hash();concurrency();forecast();System.out.println("All Chronos self-tests passed.");}private static void stats(){OnlineStats s=new OnlineStats();double[]x=new double[10000];Random r=new Random(7);double mean=0;for(int i=0;i<x.length;i++){x[i]=r.nextDouble()*100;s.update(x[i]);mean+=x[i];}mean/=x.length;double v=0;for(double z:x)v+=(z-mean)*(z-mean);v/=x.length-1;if(Math.abs(v-s.variance())>1e-9)throw new AssertionError("Welford mismatch");}private static void hash(){EventStore s=new EventStore();TransactionPosted posted=new TransactionPosted(UUID.randomUUID(),Instant.now(),LocalDate.now(),Kind.EXPENSE,Category.FOOD,Money.of("12.00"),"lunch",Optional.empty(),Optional.empty());s.append(posted);s.append(new TransactionVoided(UUID.randomUUID(),Instant.now(),posted.eventId(),"correction"));if(!s.replay(new BalanceProjection()).balance().equals(Money.ZERO))throw new AssertionError("void did not reverse projection");if(!HashChain.verify(s.all()).valid())throw new AssertionError("hash invalid");StoredEvent original=s.all().get(0);StoredEvent tampered=new StoredEvent(original.seq(),original.event(),original.prevHash(),"f".repeat(64));var report=HashChain.verify(List.of(tampered));if(report.valid()||report.brokenSeq().orElse(-1)!=1)throw new AssertionError("tamper sequence not identified");}private static void concurrency()throws Exception{EventStore s=new EventStore();LedgerWriter w=new LedgerWriter(s,new EventBus());List<Thread> ts=new ArrayList<>();for(int j=0;j<8;j++){Thread t=new Thread(()->{for(int i=0;i<625;i++)w.submit(new TransactionPosted(UUID.randomUUID(),Instant.now(),LocalDate.now(),Kind.EXPENSE,Category.FOOD,Money.of("1"),"stress",Optional.empty(),Optional.empty())).join();});ts.add(t);t.start();}for(Thread t:ts)t.join();w.close();if(s.all().size()!=5000||!HashChain.verify(s.all()).valid())throw new AssertionError("writer stress failed");}private static void forecast(){ForecastRequest q=ForecastRequest.builder().balance(1000).horizon(30).paths(500).seed(123).dailyMean(DayOfWeek.MONDAY,10).build();MonteCarloEngine e=new MonteCarloEngine(2);var a=e.simulate(q);var b=e.simulate(q);if(!Arrays.deepEquals(a.percentileBands(),b.percentileBands()))throw new AssertionError("seed not reproducible");var c=e.simulate(ForecastRequest.builder().balance(1000).horizon(30).paths(500).seed(124).dailyMean(DayOfWeek.MONDAY,10).build());if(Arrays.deepEquals(a.percentileBands(),c.percentileBands()))throw new AssertionError("different seed produced identical paths");e.close();}}
